// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address[] memory tos, uint256 v, address tokenHolder) public {
        vm.assume(tokenHolder != address(0));
        // adversarial helper: a token whose transferFrom always succeeds
        FakeToken tok = new FakeToken();
        vm.assume(tos.length > 0 && tos.length <= 4);
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
            tok.setBalance(tokenHolder, v);
        }
        vm.prank(tokenHolder);
        tok.approve(address(c), type(uint256).max);
        bool ok;
        try c.transfer(from, address(tok), tos, v) returns (bool r) { ok = r; } catch { ok = false; }
        // general rule: a non-reverting successful multi-transfer returns true
        assertTrue(ok);
    }
}

contract FakeToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function setBalance(address a, uint256 v) public { balanceOf[a] = v; }

    function approve(address s, uint256 v) public {
        allowance[msg.sender][s] = v;
    }

    function transferFrom(address from, address to, uint256 v) public returns (bool) {
        require(balanceOf[from] >= v, "insufficient");
        require(allowance[from][msg.sender] >= v, "no allowance");
        balanceOf[from] -= v;
        balanceOf[to] += v;
        allowance[from][msg.sender] -= v;
        return true;
    }
}
